import { ChangeDetectionStrategy, Component, computed, signal } from '@angular/core';
import { AevkoChartCanvas } from '../../chart';
import { AevkoBadge } from '../../badge';
import { AevkoButton } from '../../button';
import { AEVKO_CARD_IMPORTS } from '../../card';
import { AevkoSidebar } from '../../sidebar';
import {
  AevkoTable,
  AevkoTableBody,
  AevkoTableCell,
  AevkoTableContainer,
  AevkoTableHead,
  AevkoTableHeader,
  AevkoTableRow,
} from '../../table';

@Component({
  selector: 'aevko-dashboard-01-block',
  standalone: true,
  imports: [
    AevkoChartCanvas,
    AevkoBadge,
    AevkoButton,
    AevkoSidebar,
    AevkoTable,
    AevkoTableBody,
    AevkoTableCell,
    AevkoTableContainer,
    AevkoTableHead,
    AevkoTableHeader,
    AevkoTableRow,
    ...AEVKO_CARD_IMPORTS,
  ],
  templateUrl: './dashboard-01.component.html',
  styleUrl: './dashboard-01.component.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { 'data-slot': 'dashboard-01' },
})
export class AevkoDashboard01Block {
  readonly metrics = computed(() => [
    {
      label: 'Total revenue',
      value: new Intl.NumberFormat('en', {
        style: 'currency',
        currency: 'USD',
        maximumFractionDigits: 0,
      }).format(this.totalRevenue()),
      trend:
        '↗ ' +
        (
          (this.totalRevenue() /
            this.revenue().datasets[1].values.reduce((sum, value) => sum + value, 0) -
            1) *
          100
        ).toFixed(1) +
        '% from last period',
      note: 'Revenue across all channels · ' + this.period() + ' months',
    },
    {
      label: 'Active accounts',
      value: '2,840',
      trend: '↗ 8.2% from last period',
      note: 'Customers using your product',
    },
    {
      label: 'Conversion rate',
      value: '4.8%',
      trend: '↗ 0.6 percentage points',
      note: 'Visitors becoming customers',
    },
    {
      label: 'Net retention',
      value: '108%',
      trend: '↗ 3.1 percentage points',
      note: 'Growth within existing accounts',
    },
  ]);
  readonly period = signal('6');
  readonly query = signal('');
  readonly creating = signal(false);
  readonly projectName = signal('');
  readonly notice = signal('');
  readonly projects = signal([
    { name: 'Atlas migration', owner: 'Platform', status: 'On track', progress: '82%' },
    { name: 'Checkout refresh', owner: 'Commerce', status: 'At risk', progress: '58%' },
    { name: 'Research portal', owner: 'Insights', status: 'On track', progress: '71%' },
    { name: 'Mobile foundations', owner: 'Product', status: 'Planning', progress: '24%' },
  ]);
  readonly filteredProjects = computed(() =>
    this.projects().filter((project) =>
      `${project.name} ${project.owner} ${project.status}`
        .toLowerCase()
        .includes(this.query().toLowerCase()),
    ),
  );
  readonly revenue = computed(() => {
    const count = Number(this.period());
    return {
      labels: ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun'].slice(-count),
      datasets: [
        {
          label: 'Revenue',
          values: [18400, 22800, 20600, 28400, 24600, 32400].slice(-count),
          fill: true,
        },
        {
          label: 'Previous period',
          values: [14200, 16800, 18200, 21400, 19800, 24200].slice(-count),
          dashed: true,
        },
      ],
    };
  });
  readonly totalRevenue = computed(() =>
    this.revenue().datasets[0].values.reduce((sum, value) => sum + value, 0),
  );
  readonly channels = computed(() => {
    const total = this.totalRevenue();
    const direct = Math.round(total * 0.44);
    const search = Math.round(total * 0.33);
    return {
      labels: ['Direct', 'Search', 'Partners'],
      datasets: [{ label: 'Revenue', values: [direct, search, total - direct - search] }],
    };
  });
  readonly exportUrl = computed(
    () =>
      'data:text/csv;charset=utf-8,' +
      encodeURIComponent(
        'Project,Owner,Status,Progress\n' +
          this.filteredProjects()
            .map((project) =>
              [project.name, project.owner, project.status, project.progress]
                .map((value) => '"' + value.replaceAll('"', '""') + '"')
                .join(','),
            )
            .join('\n'),
      ),
  );
  addProject(event: Event): void {
    event.preventDefault();
    const name = this.projectName().trim();
    if (!name) return;
    if (this.projects().some((project) => project.name.toLowerCase() === name.toLowerCase())) {
      this.notice.set('A project with this name already exists.');
      return;
    }
    this.projects.update((projects) => [
      ...projects,
      { name, owner: 'Product', status: 'Planning', progress: '0%' },
    ]);
    this.projectName.set('');
    this.query.set('');
    this.creating.set(false);
    this.notice.set('Project created.');
  }
}

:host {
  display: block;
  color: var(--aevko-foreground, #18181b);
}
.dashboard {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  min-height: 100vh;
  background: var(--aevko-background, #fff);
}
aevko-sidebar {
  background: var(--aevko-surface, #fafafa);
}
.dashboard-nav {
  display: grid;
  gap: 0.375rem;
}
.dashboard-nav a {
  display: flex;
  gap: 0.75rem;
  align-items: center;
  padding: 0.75rem;
  color: inherit;
  text-decoration: none;
  font-size: 0.8125rem;
}
.dashboard-nav a:hover,
.dashboard-nav a[aria-current] {
  background: var(--aevko-background, #fff);
}
.dashboard-nav a span {
  width: 1rem;
  text-align: center;
}
.nav-label {
  font-size: 0.6875rem;
  color: var(--aevko-muted, #71717a);
  padding: 0.75rem;
  margin: 0;
}
[aevkoSidebarFooter] {
  display: grid;
  gap: 0.375rem;
  font-size: 0.75rem;
}
small {
  color: var(--aevko-muted, #71717a);
}
main {
  min-width: 0;
  padding: clamp(1rem, 3vw, 2.5rem);
  max-width: 100rem;
  width: 100%;
  box-sizing: border-box;
}
.dashboard-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 1.5rem;
  padding-bottom: 2rem;
}
.eyebrow {
  font-size: 0.6875rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--aevko-muted, #71717a);
  margin: 0 0 0.625rem;
}
h1 {
  margin: 0;
  font-weight: 550;
  font-size: clamp(1.75rem, 2.5vw, 2.5rem);
  letter-spacing: -0.045em;
  line-height: 1.15;
}
h2 {
  margin: 0;
  font-size: 1rem;
  font-weight: 550;
  letter-spacing: -0.02em;
}
.intro,
.description {
  color: var(--aevko-muted, #71717a);
  font-size: 0.8125rem;
  line-height: 1.6;
  margin: 0.625rem 0 0;
}
.dashboard-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  flex: none;
}
.cards {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 1rem;
  margin-bottom: 1.5rem;
}
aevko-card {
  gap: 0;
}
aevko-card-title {
  font-size: 1.875rem;
  letter-spacing: -0.04em;
  font-variant-numeric: tabular-nums;
}
.trend {
  font-size: 0.8125rem;
  font-weight: 500;
}
.metric-note {
  font-size: 0.75rem;
  color: var(--aevko-muted, #71717a);
  margin: 0.5rem 0 0;
}
.dashboard-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.65fr) minmax(0, 1fr);
  gap: 1.5rem;
}
.chart {
  min-width: 0;
  border: 1px solid var(--aevko-border, #e4e4e7);
  padding: 1.25rem;
}
.chart > header {
  display: flex;
  justify-content: space-between;
  align-items: start;
  gap: 1rem;
  flex-wrap: wrap;
  margin-bottom: 1.75rem;
}
input,
select {
  font: inherit;
  font-size: 0.8125rem;
  color: inherit;
  border: 1px solid var(--aevko-border, #e4e4e7);
  background: var(--aevko-background, #fff);
  min-height: 2.5rem;
  padding: 0.5rem 0.75rem;
  box-sizing: border-box;
  max-width: 100%;
}
input:focus-visible,
select:focus-visible,
a:focus-visible {
  outline: 2px solid var(--aevko-focus, #71717a);
  outline-offset: 2px;
}
.projects {
  margin-top: 1.5rem;
  border: 1px solid var(--aevko-border, #e4e4e7);
  min-width: 0;
}
.projects > header {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 1.25rem;
}
.count {
  display: inline-block;
  margin-inline-start: 0.5rem;
  padding: 0.125rem 0.375rem;
  font-size: 0.6875rem;
  background: var(--aevko-surface, #f4f4f5);
  vertical-align: middle;
}
.table-note {
  margin: 0;
  padding: 1rem 1.25rem;
  font-size: 0.75rem;
  color: var(--aevko-muted, #71717a);
}
.progress-track {
  display: inline-block;
  width: 3rem;
  height: 0.25rem;
  background: var(--aevko-border, #e4e4e7);
  margin-inline-end: 0.75rem;
  vertical-align: middle;
}
.progress-track span {
  display: block;
  height: 100%;
  background: var(--aevko-foreground, #18181b);
}
.activity {
  padding-top: 2rem;
}
.activity > div {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1rem;
  margin-top: 1rem;
}
.activity p {
  display: grid;
  gap: 0.375rem;
  font-size: 0.75rem;
  margin: 0;
  border-inline-start: 2px solid var(--aevko-border, #e4e4e7);
  padding-inline-start: 0.875rem;
}
.activity strong {
  font-weight: 500;
}
.activity span {
  color: var(--aevko-muted, #71717a);
}
.project-form {
  display: flex;
  gap: 0.75rem;
  align-items: center;
  flex-wrap: wrap;
  padding: 1rem;
  border: 1px solid var(--aevko-border, #e4e4e7);
  margin-bottom: 1rem;
  font-size: 0.875rem;
}
.notice {
  font-size: 0.875rem;
  margin: 0 0 1rem;
}
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}
@media (max-width: 1150px) {
  .cards {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .dashboard-grid {
    grid-template-columns: minmax(0, 1fr);
  }
  .dashboard-header {
    align-items: start;
    flex-direction: column;
  }
}
@media (max-width: 760px) {
  .dashboard {
    grid-template-columns: minmax(0, 1fr);
  }
  aevko-sidebar {
    padding: 0.75rem 1rem;
  }
  .dashboard-actions {
    width: 100%;
  }
  .activity > div {
    grid-template-columns: minmax(0, 1fr);
  }
  .chart {
    padding: 1rem;
  }
}
@media (max-width: 400px) {
  .cards {
    gap: 0.5rem;
  }
  aevko-card-title {
    font-size: 1.5rem;
  }
  .project-form input {
    width: 100%;
  }
}

.dashboard-actions a {
  display: inline-flex;
  align-items: center;
  padding: 0.625rem 1rem;
  border: 1px solid var(--aevko-border, #e4e4e7);
  text-decoration: none;
  color: inherit;
  font-size: 0.875rem;
  min-height: 2.75rem;
  box-sizing: border-box;
}
aevko-sidebar[data-collapsed='true'] .dashboard-nav a {
  font-size: 0;
  justify-content: center;
}
aevko-sidebar[data-collapsed='true'] .dashboard-nav a span {
  font-size: 1rem;
}
aevko-sidebar[data-collapsed='true'] .nav-label {
  display: none;
}
